import{_ as a,c as s,o as n,ah as t}from"./chunks/framework.l36K22_3.js";const u=JSON.parse('{"title":"fork 别人的代码，如何更新主分支最新代码","description":"","frontmatter":{},"headers":[],"relativePath":"common-tools/git/fork.md","filePath":"common-tools/git/fork.md","lastUpdated":1788862675000}'),i={name:"common-tools/git/fork.md"};function p(r,e,o,l,c,d){return n(),s("div",null,e[0]||(e[0]=[t(`<h1 id="fork-别人的代码-如何更新主分支最新代码" tabindex="-1">fork 别人的代码，如何更新主分支最新代码 <a class="header-anchor" href="#fork-别人的代码-如何更新主分支最新代码" aria-label="Permalink to &quot;fork 别人的代码，如何更新主分支最新代码&quot;">​</a></h1><blockquote><p>fork 操作：就是从别的大佬远程端 <code>git仓库</code> 拷贝一份到自己的 <code>git仓库</code>。</p></blockquote><p>在开发学习时，经常通过 fork 别人的 git 开源项目进行开发学习。 所以在我们开发完成后，想合并到大佬的主分支去，我们需要进行创建一个 <code>merge request</code>， 提交给主分支代码管理员进行代码审核，审核通过后允许 <code>merge</code>，这样我们开发的代码就会合并到主项目中。</p><p>那么大佬的主分支有更新了，我们怎样将主分支的更新代码拉取、合并到本地呢？</p><h2 id="fork-分支更新流程" tabindex="-1">fork 分支更新流程： <a class="header-anchor" href="#fork-分支更新流程" aria-label="Permalink to &quot;fork 分支更新流程：&quot;">​</a></h2><h3 id="_1-首先要确认是否建立了主项目的远程源" tabindex="-1">1. 首先要确认是否建立了主项目的远程源： <a class="header-anchor" href="#_1-首先要确认是否建立了主项目的远程源" aria-label="Permalink to &quot;1. 首先要确认是否建立了主项目的远程源：&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git remote -v</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果只显示自己的两个源（fetch, push）如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tonyt@xiaofeng web-poc % git remote -v</span></span>
<span class="line"><span>origin  http://10.25.0.130/web-tools/web-poc.git (fetch)</span></span>
<span class="line"><span>origin  http://10.25.0.130/web-tools/web-poc.git (push)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_2-则说明没有建立远程的-repo-源-需要添加主-repo-的源" tabindex="-1">2. 则说明没有建立远程的 repo 源，需要添加主 repo 的源： <a class="header-anchor" href="#_2-则说明没有建立远程的-repo-源-需要添加主-repo-的源" aria-label="Permalink to &quot;2. 则说明没有建立远程的 repo 源，需要添加主 repo 的源：&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git remote add upstream https://github.com/b******/c*****.git    # git remote add upstream URL</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这里的 upstream 是我们建立的远程 branch 的一个本地名。对于 url 一般有 https 与 ssh 的方式，如果是 ssh 方式，则需要添加 ssh 的 url,不能添加 https 的方式，否则不能在 ssh 下访问该 url。</p><h3 id="_3-添加完之后再次使用-git-remote-v-来确认。" tabindex="-1">3. 添加完之后再次使用 <code>git remote -v</code> 来确认。 <a class="header-anchor" href="#_3-添加完之后再次使用-git-remote-v-来确认。" aria-label="Permalink to &quot;3. 添加完之后再次使用 \`git remote -v\` 来确认。&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tonyt@xiaofeng web-poc % git remote -v</span></span>
<span class="line"><span>origin  http://10.25.2.87:9980/root/web-poc.git (fetch)</span></span>
<span class="line"><span>origin  http://10.25.2.87:9980/root/web-poc.git (push)</span></span>
<span class="line"><span>upstream        http://10.25.0.130/web-tools/web-poc.git (fetch)</span></span>
<span class="line"><span>upstream        http://10.25.0.130/web-tools/web-poc.git (push)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>有 upstream 这样就是已经创建了主 repo 的远程源。</p><h3 id="_4-拉取主-repo-源代码" tabindex="-1">4. 拉取主 repo 源代码： <a class="header-anchor" href="#_4-拉取主-repo-源代码" aria-label="Permalink to &quot;4. 拉取主 repo 源代码：&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> $ git fetch upstream</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_5-合并主-repo-代码到本地代码" tabindex="-1">5. 合并主 repo 代码到本地代码： <a class="header-anchor" href="#_5-合并主-repo-代码到本地代码" aria-label="Permalink to &quot;5. 合并主 repo 代码到本地代码：&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git merge upstream/master</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_6-大功告成" tabindex="-1">6. 大功告成！！！！ <a class="header-anchor" href="#_6-大功告成" aria-label="Permalink to &quot;6. 大功告成！！！！&quot;">​</a></h3>`,20)]))}const b=a(i,[["render",p]]);export{u as __pageData,b as default};
